INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'card_description', 'Rivers wrap Burnt Fen on three sides: low-lying prime farmland between Littleport and Mildenhall, where a remarkable amount of Mesolithic archaeology has come to light.', 'The area shows a remarkable amount of archaeological findings of the Mesolithic period.', 'teaser-card-s002-rollback:00daa905-2060-4b9c-8369-eb5e6878f6a6:card_description', 'rollback of teaser-card-s002: card_description ''The area shows a remarkable amount of archaeological findings of the Mesolithic period.'' restored on Burnt Fen', '39ad69b8c42fc03e4f24c468ec9a5f7d2107b7f89909971c68d8fa5e8ffe6a82|8c848bf9cb02819901d64fbf1a965d70698355cadf76dab7d9e7a586eff108cf|8c848bf9cb02819901d64fbf1a965d70698355cadf76dab7d9e7a586eff108cf', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Rivers wrap Burnt Fen on three sides: low-lying prime farmland between Littleport and Mildenhall, where a remarkable amount of Mesolithic archaeology has come to light."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Burnt Fen is surrounded by rivers on three sides [S2]; it is low-lying land [S1]; it is prime agricultural land [S2]; it lies between Littleport and Mildenhall [S1]; a remarkable amount of Mesolithic archaeological findings has been made there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Burnt Fen is an area of low-lying land (fen farmland) in England lying between Littleport and Mildenhall [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; Burnt Fen is low-lying land [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; Rivers wrap Burnt Fen on three sides [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; Burnt Fen is prime farmland [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; A remarkable amount of Mesolithic archaeology has come to light at Burnt Fen [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]"}]'::jsonb),
    ('0151be4b-c7d5-487f-8844-27e110594270'::uuid, 'card_description', 'Beside the Roman road to Sawley on the River Trent, 600m east of the Derventio fort in Little Chester, lies the Derby Racecourse Roman Settlement, founded around AD 90.', 'The Derby Racecourse Roman settlement was the third settlement in Derby or Derventio which was a small town in the Roman province of Britannia.', 'teaser-card-s002-rollback:0151be4b-c7d5-487f-8844-27e110594270:card_description', 'rollback of teaser-card-s002: card_description ''The Derby Racecourse Roman settlement was the third settlement in Derby or Derventio which was a small town in the Roman province of Britannia.'' restored on Derby Racecourse Roman Settlement', '45e62b9e3fa0796839fc5bb39eefed90830f6a803ebcef00c5032f278da5a58e|8dd952ec9ba53cdeabe99a856fd23a64e2cfe47b5481d3aae8bc82edccdc52c5|8dd952ec9ba53cdeabe99a856fd23a64e2cfe47b5481d3aae8bc82edccdc52c5', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beside the Roman road to Sawley on the River Trent, 600m east of the Derventio fort in Little Chester, lies the Derby Racecourse Roman Settlement, founded around AD 90."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the settlement lies beside (is passed by) the Roman road to Sawley [S3]; Sawley is on the River Trent [S3]; it lies 600m east of the Derventio fort [S2]; the Derventio fort is in Little Chester [S2]; the settlement is Roman [S1]; it was founded around AD 90 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Derby Racecourse Roman Settlement is a Roman civilian settlement (vicus) [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4537]; The settlement is at Derby, England [SUPPORTED: https://en.wikipedia.org/wiki/Derby_Racecourse_Roman_settlement]; The settlement lies beside a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Derby_Racecourse_Roman_settlement]; That Roman road runs to Sawley [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4537]; Sawley lies on the River Trent [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4537]; The settlement lies 600m east of the Roman fort in Little Chester [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4537]; The fort in Little Chester is the Derventio fort [SUPPORTED: https://en.wikipedia.org/wiki/Derby_Racecourse_Roman_settlement]; The settlement was founded around AD 90 [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4537]"}]'::jsonb),
    ('019ea3e7-663b-4a60-863a-980007df6878'::uuid, 'card_description', 'Modelled after Djoser''s step pyramid, the Pyramid of Sekhemkhet at Saqqara held a sarcophagus cut from a single block of fine alabaster, its lid slid into place and sealed with mortar.', 'An unfinished step pyramid from 2645 BC, abandoned so early it was buried under sand. The sealed sarcophagus inside was found completely empty.', 'teaser-card-s002-rollback:019ea3e7-663b-4a60-863a-980007df6878:card_description', 'rollback of teaser-card-s002: card_description ''An unfinished step pyramid from 2645 BC, abandoned so early it was buried under sand. The sealed sarcophagus inside was found completely empty.'' restored on Pyramid of Sekhemkhet- Buried Pyramid', '7709dfff9d1d6d01b4c0d2a9b71068a7bf471afe55c3186741d285b4aeab4676|a453c48f56a99c26112cb2776c463ae853a4d61c40fc3fcbd85e067b72f3af5b|a453c48f56a99c26112cb2776c463ae853a4d61c40fc3fcbd85e067b72f3af5b', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Modelled after Djoser''s step pyramid, the Pyramid of Sekhemkhet at Saqqara held a sarcophagus cut from a single block of fine alabaster, its lid slid into place and sealed with mortar."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the pyramid was modelled after Djoser''s step pyramid [S1]; the Pyramid of Sekhemkhet is at Saqqara [S2]; the pyramid held a sarcophagus [S6, S7]; the sarcophagus is cut from a single block of fine alabaster [S7]; the sarcophagus lid was slid into place [S7]; the lid was sealed with mortar [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Pyramid of Sekhemkhet (Buried Pyramid) is a step pyramid at Saqqara, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; It is a step pyramid built for Sekhemkhet (left unfinished) [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; It was modelled after Djoser''s step pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; The pyramid held a sarcophagus [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; The sarcophagus was cut from a single block of fine alabaster [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; The sarcophagus lid was slid into place [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]; The lid was sealed with mortar [SUPPORTED: https://en.wikipedia.org/wiki/Buried_Pyramid]"}]'::jsonb),
    ('0248e2bc-e43e-4bb6-8435-b9f9cac52040'::uuid, 'card_description', 'Cyrus the Great founded Pasargadae near where he defeated Astyages. Its ruins hold a mausoleum commonly believed to be his, a fortress on a hill and the earliest known fourfold garden.', 'Founded around 550 BC by Cyrus the Great as the first capital of the Achaemenid Empire, Pasargadae covers 1.6 square kilometres. A stone mausoleum on site is widely identified as Cyrus''s own tomb.', 'teaser-card-s002-rollback:0248e2bc-e43e-4bb6-8435-b9f9cac52040:card_description', 'rollback of teaser-card-s002: card_description "Founded around 550 BC by Cyrus the Great as the first capital of the Achaemenid Empire, Pasargadae covers 1.6 square kilometres. A stone mausoleum on site is widely identified as Cyrus''s own tomb." restored on Pasargadae', '9cd5d3af52603ae62f65d7e89b11a9b0d38e114d083a21013cc8d8a3748c076e|744d9fd2b0af5710e6b9f2e5e1b234d18da8a995005bb7367f696c28087ce766|744d9fd2b0af5710e6b9f2e5e1b234d18da8a995005bb7367f696c28087ce766', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cyrus the Great founded Pasargadae near where he defeated Astyages. Its ruins hold a mausoleum commonly believed to be his, a fortress on a hill and the earliest known fourfold garden."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cyrus the Great founded Pasargadae [S2]; it was founded near the site where Cyrus defeated Astyages [S2]; its ruins include a mausoleum commonly believed to be that of Cyrus [S5]; its ruins include a fortress on a hill [S5]; it holds the earliest known fourfold garden [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pasargadae is the ruins of an ancient city (the first Achaemenid capital) in Iran [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; Cyrus the Great founded Pasargadae [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; Pasargadae was founded near the place where Cyrus defeated Astyages [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; The ruins include a mausoleum commonly believed to be that of Cyrus [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; The attribution of the mausoleum to Cyrus is a common belief rather than a certainty [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; The ruins include a fortress on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]; Pasargadae holds the earliest known fourfold garden [SUPPORTED: https://en.wikipedia.org/wiki/Pasargadae]"}]'::jsonb),
    ('028deb2a-ddfb-43d8-94bf-e8f64a6e21da'::uuid, 'card_description', 'On a hilltop west of Newcastle stood Condercum, third fort on Hadrian''s Wall, built between 122 and 124 AD. A hundred yards east, the remains of a temple to Antenociticus can still be seen.', 'Built in 122 AD, this was the third fort on Hadrian''s Wall — west of Segedunum and Pons Aelius. Today it is invisible beneath a housing estate and reservoir in Benwell, Newcastle.', 'teaser-card-s002-rollback:028deb2a-ddfb-43d8-94bf-e8f64a6e21da:card_description', 'rollback of teaser-card-s002: card_description "Built in 122 AD, this was the third fort on Hadrian''s Wall — west of Segedunum and Pons Aelius. Today it is invisible beneath a housing estate and reservoir in Benwell, Newcastle." restored on Condercum', '29dbb994d118a7df60cd78780f4fbe1ceee2cd7555499b9b8010cdcdbd4d4afd|2be5b2df7b0c2ebd40bb3eebb38ab2f0f8a9ae6341c5ca5a0a7622e067858f77|2be5b2df7b0c2ebd40bb3eebb38ab2f0f8a9ae6341c5ca5a0a7622e067858f77', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a hilltop west of Newcastle stood Condercum, third fort on Hadrian''s Wall, built between 122 and 124 AD. A hundred yards east, the remains of a temple to Antenociticus can still be seen."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Condercum stood on a hilltop [S2]; it lay west of Newcastle [S1, S2]; it was the third fort on Hadrian''s Wall [S2]; it was built between 122 and 124 AD [S3]; the remains of a temple to Antenociticus lie a hundred yards east of the fort [S8]; those temple remains can still be seen [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Condercum was a Roman fort on Hadrian''s Wall at Benwell, Newcastle upon Tyne, England [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; Condercum stood on a hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; Condercum lay west of Newcastle [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; Condercum was the third fort on Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; Condercum was built between 122 and 124 AD [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; A temple to Antenociticus stood a hundred yards east of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Condercum]; The remains of the temple to Antenociticus can still be seen [SUPPORTED: https://www.english-heritage.org.uk/visit/places/benwell-roman-temple-hadrians-wall/]"}]'::jsonb),
    ('02941d88-16e9-42c6-8abf-e7d5b5b38821'::uuid, 'card_description', 'Above Bath and the River Avon, the limestone plateau of Bathampton Down has yielded Mesolithic flints, and holds four reported Bronze Age barrows and an Iron Age hillfort or stock enclosure.', 'The first evidence of human activity is from the Mesolithic period and consists of a dispersed collection of flint finds, including hammerstones, cores, fragments of axes and arrowheads.', 'teaser-card-s002-rollback:02941d88-16e9-42c6-8abf-e7d5b5b38821:card_description', 'rollback of teaser-card-s002: card_description ''The first evidence of human activity is from the Mesolithic period and consists of a dispersed collection of flint finds, including hammerstones, cores, fragments of axes and arrowheads.'' restored on Bathampton Down', '240c4337b36f08a2ab73436949279a5eed6430cff3d274f46fc4ad14caab11b8|6af3d40c1ebb502f769a7a2c49fd265d60f02d5f1e7b69be6d57561045ce733a|6af3d40c1ebb502f769a7a2c49fd265d60f02d5f1e7b69be6d57561045ce733a', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Above Bath and the River Avon, the limestone plateau of Bathampton Down has yielded Mesolithic flints, and holds four reported Bronze Age barrows and an Iron Age hillfort or stock enclosure."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Bathampton Down overlooks Bath and the River Avon [S1]; it is a limestone plateau [S1]; it has yielded Mesolithic flint finds [S3]; four Bronze Age barrows have been reported there (hedge kept) [S4]; it has an Iron Age hillfort or stock enclosure [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Bathampton Down is a limestone plateau above Bath and the River Avon, in England [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It lies above Bath [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It lies above the River Avon [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It is a limestone plateau [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It has yielded Mesolithic flints [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It holds four reported Bronze Age barrows [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]; It holds an Iron Age hillfort or stock enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Bathampton_Down]"}]'::jsonb),
    ('02c083c6-8552-4edb-8b3d-26d649280de5'::uuid, 'card_description', 'At Apadana Castle Shush stood the Palace of Darius in Susa, where the Persian column topped by two bulls was probably developed. Once destroyed by fire and partly restored, little remains.', 'Built 521–515 BC as the winter palace of Darius I on the ruins of an Elamite city. Alexander burned it in 330 BC. A handful of pillars and partial walls survive of one of antiquity’s grandest courts.', 'teaser-card-s002-rollback:02c083c6-8552-4edb-8b3d-26d649280de5:card_description', 'rollback of teaser-card-s002: card_description ''Built 521–515 BC as the winter palace of Darius I on the ruins of an Elamite city. Alexander burned it in 330 BC. A handful of pillars and partial walls survive of one of antiquity’s grandest courts.'' restored on Apadana Castle Shush', 'ea388411d23641ae41824ad351420d169ce9ae73e6305819c65bea5c244cd935|9ce43bed59a00ba112d08ffdd636428ab7851b7a15bb301bdc71937db6d113fb|9ce43bed59a00ba112d08ffdd636428ab7851b7a15bb301bdc71937db6d113fb', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Apadana Castle Shush stood the Palace of Darius in Susa, where the Persian column topped by two bulls was probably developed. Once destroyed by fire and partly restored, little remains."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Palace of Darius in Susa stood at this site [S1]; the distinctive Persian column topped by two bulls was probably developed there (hedge kept) [S7]; the palace was once destroyed by fire [S4, S6]; it was partially restored [S4, S6]; little of it remains [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Apadana Castle Shush stood the Palace of Darius in Susa, an Achaemenid palace complex in Susa (Shush), Iran [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]; The palace complex at Susa included an apadana (the site''s name) [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]; Shush is Susa [SUPPORTED: https://en.wikipedia.org/wiki/Shush,_Iran]; The Persian column topped by two bulls was probably developed there [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]; The Persian column style was probably developed in the Palace of Darius in Susa (second source) [SUPPORTED: https://en.wikipedia.org/wiki/Persian_column]; The palace was once destroyed by fire [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]; The palace was partly restored [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]; Little remains of it [SUPPORTED: https://en.wikipedia.org/wiki/Palace_of_Darius_in_Susa]"}]'::jsonb),
    ('033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe'::uuid, 'card_description', 'Where the Sava meets the Danube stands the Belgrade Fortress. The Celtic Scordisci founded Singidunum here in the 3rd century BC; Goths and Huns later repeatedly destroyed its Roman camp.', 'Singidunum was defended by the Roman legion IV Flaviae, which built a fortified camp on a hill at the confluence of the Danube and the Sava rivers.', 'teaser-card-s002-rollback:033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe:card_description', 'rollback of teaser-card-s002: card_description ''Singidunum was defended by the Roman legion IV Flaviae, which built a fortified camp on a hill at the confluence of the Danube and the Sava rivers.'' restored on Belgrade Fortress', 'db3b5a486901197b6b86e8f4ac9c4c85b5c56fe0fd0bd699d0f60518e0cb5082|a2e38a1f09d98d3425be5b5768cbcba0dd74a1d41d1dc94d0faeadc3a64e3793|a2e38a1f09d98d3425be5b5768cbcba0dd74a1d41d1dc94d0faeadc3a64e3793', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Where the Sava meets the Danube stands the Belgrade Fortress. The Celtic Scordisci founded Singidunum here in the 3rd century BC; Goths and Huns later repeatedly destroyed its Roman camp."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Belgrade Fortress stands at the confluence of the Sava and the Danube [S2]; the Scordisci were a Celtic tribe [S3]; the Scordisci founded Singidunum here [S3]; the founding was in the 3rd century BC [S3]; there was a Roman camp here [S5]; Goths and Huns later repeatedly destroyed that Roman camp [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The 