    ('038e5559-6e30-4520-ad95-4ba9679b24a6'::uuid, 'card_description', 'Where the Altmühl meets the Danube, on a peninsula inhabited more or less constantly since 13,000 BCE, the Celtic oppidum of Alcimoennis crowned the Michelsberg hill above Kelheim.', 'A Celtic oppidum from 500-50 BC at the confluence of the Danube and Altmühl rivers. The peninsula it occupies has been inhabited continuously since 13,000 BC.', 'teaser-card-s002-rollback:038e5559-6e30-4520-ad95-4ba9679b24a6:card_description', 'rollback of teaser-card-s002: card_description ''A Celtic oppidum from 500-50 BC at the confluence of the Danube and Altmühl rivers. The peninsula it occupies has been inhabited continuously since 13,000 BC.'' restored on Alcimoennis', '9a81e6465ac3e5479cf087e998fe02a63f55d85a3ddd376676b16e3f972a0751|67581408b5193b65079224a89269009a435c4db98033b574ccbab7b5394da21e|67581408b5193b65079224a89269009a435c4db98033b574ccbab7b5394da21e', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Where the Altmühl meets the Danube, on a peninsula inhabited more or less constantly since 13,000 BCE, the Celtic oppidum of Alcimoennis crowned the Michelsberg hill above Kelheim."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is at the confluence of the Altmühl and the Danube [S2]; it is on a peninsula [S2]; the peninsula has been inhabited more or less constantly since 13,000 BCE [S3]; Alcimoennis was a Celtic oppidum [S1]; it sat on (dominated from) the Michelsberg hill [S2]; it lay above Kelheim [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Alcimoennis was 