    ('041049ae-edd9-49a3-8233-1ea9b3382913'::uuid, 'card_description', 'For a few decades after the Roman invasion of 43 AD, the Fosse Way marked Rome''s western frontier. For 182 miles, Lincoln to Ilchester, it never strays over 6 miles from a straight line.', 'The road joined Akeman Street and Ermin Way at Cirencester, crossed Watling Street at Venonis south of Leicester, and joined Ermine Street at Lincoln.', 'teaser-card-s002-rollback:041049ae-edd9-49a3-8233-1ea9b3382913:card_description', 'rollback of teaser-card-s002: card_description ''The road joined Akeman Street and Ermin Way at Cirencester, crossed Watling Street at Venonis south of Leicester, and joined Ermine Street at Lincoln.'' restored on Fosse Way', '3f177ebcfcb75ebbf0d04db7cf85d7ed1d64de744209d86a6b1d8db6a5e67654|847f6f9af1c68216c4076dd063f082cc56fd27e48ac1130c03891b952a65abc1|847f6f9af1c68216c4076dd063f082cc56fd27e48ac1130c03891b952a65abc1', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "For a few decades after the Roman invasion of 43 AD, the Fosse Way marked Rome''s western frontier. For 182 miles, Lincoln to Ilchester, it never strays over 6 miles from a straight line."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Roman invasion took place in 43 AD [S1]; for a few decades after it the Fosse Way marked the western frontier of Roman rule [S1]; the route runs 182 miles from Lincoln to Ilchester [S4]; over that distance it never deviates more than 6 miles from a straight line [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Fosse Way is a Roman road in Britain