    ('042c8c7f-1ec1-485a-ba0b-3ab847320ee7'::uuid, 'card_description', 'From the Maya palace of Labna, approximately 120 m long, a ceremonial road leads to an elaborately decorated arch: not an entrance to the city, but a passage between its public areas.', 'A Maya ceremonial center from 862 AD in the Puuc Hills, with a 120-metre palace and an elaborate arch gateway linking buildings via a ceremonial road.', 'teaser-card-s002-rollback:042c8c7f-1ec1-485a-ba0b-3ab847320ee7:card_description', 'rollback of teaser-card-s002: card_description ''A Maya ceremonial center from 862 AD in the Puuc Hills, with a 120-metre palace and an elaborate arch gateway linking buildings via a ceremonial road.'' restored on Labna', '4a3f6182b23c74c46026d71c617321ec709051fc85d12cde89cbf2f9863e731f|8bc887c0fccaaa08ad8a785e1ef59afaee709e91bb7e8206569c134ded116962|8bc887c0fccaaa08ad8a785e1ef59afaee709e91bb7e8206569c134ded116962', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "From the Maya palace of Labna, approximately 120 m long, a ceremonial road leads to an elaborately decorated arch: not an entrance to the city, but a passage between its public areas."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Labna is a Maya site [S1]; it has a palace [S6, S7]; the palace is approximately 120 m long [S6]; a ceremonial road leads from the palace to an arch [S7]; the arch is elaborately decorated [S7]; the arch is not an entrance to the city [S8]; the arch is a passageway between public areas [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Labna is an archaeological site 