    ('04b79866-b13b-4b76-ae03-6392651eecab'::uuid, 'card_description', 'At the summit of a lava dome, around 1,435 meters up, the Temple of Mercury rose in trachyte in the 2nd century, replacing a temple apparently too small for the many pilgrims who came.', 'A 2nd-century AD temple built atop a volcanic summit to replace a smaller version that couldn''t handle the pilgrim crowds. Its facade faced east toward sunrise.', 'teaser-card-s002-rollback:04b79866-b13b-4b76-ae03-6392651eecab:card_description', 'rollback of teaser-card-s002: card_description "A 2nd-century AD temple built atop a volcanic summit to replace a smaller version that couldn''t handle the pilgrim crowds. Its facade faced east toward sunrise." restored on Temple of Mercury, Puy de Dôme', '656f199bf065321a35cd74f6a54e2ca116fe7ccb04a163f7c3857ff4c8bcaf4a|06c9bdc49e3bd64d4c9ac89f837cc63964061c136f116d7bfbf7f98c06610444|06c9bdc49e3bd64d4c9ac89f837cc63964061c136f116d7bfbf7f98c06610444', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At the summit of a lava dome, around 1,435 meters up, the Temple of Mercury rose in trachyte in the 2nd century, replacing a temple apparently too small for the many pilgrims who came."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Temple of Mercury stands at the summit of a lava dome [S1]; it is at an altitude of around 1,435 meters [S5]; it was built of trachyte [S1, S6]; it was built in the 2nd century [S1]; it replaced an earlier temple on the site [S2]; the earlier temple was apparently too small for the many pilgrims who visited (hedge kept) [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Temple of Mercury is a Gallo-Roman temple at the summit of the Puy de Dôme, a lava dome in France [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; The Puy de Dôme is a lava dome [SUPPORTED: https://en.wikipedia.org/wiki/Puy_de_D%C3%B4me]; The temple stands at the summit of the dome [SUPPORTED: https://en.wikipedia.org/wiki/Puy_de_D%C3%B4me]; The temple lies around 1,435 meters up [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; The temple was built of trachyte [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; The temple was built in the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; The temple was dedicated to Mercury [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; It replaced an earlier temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; The earlier temple was apparently too small for the pilgrims [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]; Many pilgrims came to the site [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Mercury_(Puy_de_D%C3%B4me)]"}]'::jsonb),
