    ('296ed0f4-1ad0-4929-b019-196c80e547be'::uuid, 'card_description', 'Just outside Hemet, in Reinhardt Canyon within the Lakeview Mountains, lies the Hemet Maze Stone, a prehistoric petroglyph whose stone and land became a California state landmark in 1956.', 'A prehistoric petroglyph carved with an intricate swastika-like maze pattern unique in rock art. Its meaning and the identity of its makers remain unknown.', 'teaser-card-s002-rollback:296ed0f4-1ad0-4929-b019-196c80e547be:card_description', 'rollback of teaser-card-s002: card_description ''A prehistoric petroglyph carved with an intricate swastika-like maze pattern unique in rock art. Its meaning and the identity of its makers remain unknown.'' restored on Hemet Maze Stone', '6106ef04ca8062c102fdcc49996d570ed545886c4f1542e0d9260251df089f87|a8e7d3b048a36ddddfaf028f51af35efc44cf56d5f6fc5c8dec2db5e24d6a28c|a8e7d3b048a36ddddfaf028f51af35efc44cf56d5f6fc5c8dec2db5e24d6a28c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Just outside Hemet, in Reinhardt Canyon within the Lakeview Mountains, lies the Hemet Maze Stone, a prehistoric petroglyph whose stone and land became a California state landmark in 1956."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it lies just outside Hemet [S2]; it is in Reinhardt Canyon [S2]; Reinhardt Canyon is within the Lakeview Mountains [S2]; the Hemet Maze Stone is a prehistoric petroglyph [S1]; the stone and its surrounding land became a California state landmark [S3]; the designation was in 1956 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Hemet Maze Stone is a prehistoric petroglyph just outside Hemet, in Reinhardt Canyon within the Lakeview Mountains [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; The maze carving is prehistoric [SUPPORTED: https://ohp.parks.ca.gov/ListedResources/Detail/557]; The site is a petroglyph (a carved image) [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; It lies just outside Hemet [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; It lies in Reinhardt Canyon [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; It lies within the Lakeview Mountains [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; The stone and its land became a California state landmark [SUPPORTED: https://en.wikipedia.org/wiki/Hemet_Maze_Stone]; The landmark designation dates to 1956 [SUPPORTED: https://ohp.parks.ca.gov/ListedResources/Detail/557]"}]'::jsonb),
    ('29d6fc00-4e39-4707-bea6-237454b055fb'::uuid, 'card_description', 'Near Turgut stood Lagina, with a monumental temple of Hecate where great festivals were celebrated every year. Little is known of its early days, though it existed by the 4th century BCE.', 'A 4th-century BC sanctuary to Hecate — goddess of crossroads and magic — in ancient Caria. The ruins of her temple here are among the best-preserved devoted to that deity.', 'teaser-card-s002-rollback:29d6fc00-4e39-4707-bea6-237454b055fb:card_description', 'rollback of teaser-card-s002: card_description ''A 4th-century BC sanctuary to Hecate — goddess of crossroads and magic — in ancient Caria. The ruins of her temple here are among the best-preserved devoted to that deity.'' restored on Lagina', 'f8baa1c24074629f3e9e29aaf19ad19b36a8d9f39921c43f3d86c475a2f87fe5|b4968000847c918d87b0ea07225cc63aca69e18c57166df7a87b6278330405b1|b4968000847c918d87b0ea07225cc63aca69e18c57166df7a87b6278330405b1', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near Turgut stood Lagina, with a monumental temple of Hecate where great festivals were celebrated every year. Little is known of its early days, though it existed by the 4th century BCE."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Lagina''s site is near Turgut [S4]; it had a monumental temple of Hecate [S2]; great festivals were celebrated there every year [S2]; little is known of its early history [S5]; it existed by (as early as) the 4th century BCE [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Lagina was an ancient town and sanctuary near Turgut [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]; Lagina stood near Turgut [SUPPORTED: https://muze.gov.tr/muze-detay?sectionId=MLG01&distId=MRK]; Lagina''s site lies near Turgut (location of the site) [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]; Lagina had a monumental temple of Hecate [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]; Great festivals were celebrated there every year [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]; Little is known of Lagina''s early days [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]; Lagina existed by the 4th century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Lagina]"}]'::jsonb),
    ('2a87862a-98dc-4cbd-8d8e-89f7c1368e63'::uuid, 'card_description', 'On Anglesey, near the Afon Braint, Caer Lêb lies within a double row of pentangular banks and marshy ditches. Its name means Leaven Castle, and under a layer of peat lay periwinkle shells.', 'A Roman and medieval site with a double row of pentangular banks and marshy ditches. Based on similar sites, it may date to the 2nd century BC.', 'teaser-card-s002-rollback:2a87862a-98dc-4cbd-8d8e-89f7c1368e63:card_description', 'rollback of teaser-card-s002: card_description ''A Roman and medieval site with a double row of pentangular banks and marshy ditches. Based on similar sites, it may date to the 2nd century BC.'' restored on Caer Lêb', '35419fc2038c3ac43d184211cc8b4ec421dee27d4bb120e424fb5bb575c0a2d6|edc0e2490ad7eb12ec0edb1ea0955b7fe3e00c46467d38e2c84d97c4f7649b39|edc0e2490ad7eb12ec0edb1ea0955b7fe3e00c46467d38e2c84d97c4f7649b39', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On Anglesey, near the Afon Braint, Caer Lêb lies within a double row of pentangular banks and marshy ditches. Its name means Leaven Castle, and under a layer of peat lay periwinkle shells."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Caer Lêb is on Anglesey [S1]; it is near the Afon Braint [S3]; it has a double row of pentangular banks [S3]; it has marshy ditches [S3]; its name means Leaven Castle [S2]; periwinkle shells lay under a layer of peat [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Caer Lêb is an earthwork enclosure (an enclosed settlement site) on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]; Caer Lêb lies near the Afon Braint [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]; The site lies within a double row of banks [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]; The banks are pentangular [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]; The ditches are marshy [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]; The name Caer Lêb means Leaven Castle [SUPPORTED, no proving quote: https://www.britainexpress.com/wales/anglesey/caer-leb.htm]; Periwinkle shells were found under a layer of peat [SUPPORTED: https://en.wikipedia.org/wiki/Caer_L%C3%AAb]"}]'::jsonb),
    ('2d76f228-e78d-4e1a-934e-cf8eef944e37'::uuid, 'card_description', 'In the Thalbach quarter of Bregenz lies a Roman Theatre built for more than 2000 visitors, by far more than the town''s population needed in Roman times. It was excavated in 2013 and 2019.', 'The theatre was excavated by archaeologists specifically in 2013 and 2019 in the name of the Vorarlberg provincial museum.', 'teaser-card-s002-rollback:2d76f228-e78d-4e1a-934e-cf8eef944e37:card_description', 'rollback of teaser-card-s002: card_description ''The theatre was excavated by archaeologists specifically in 2013 and 2019 in the name of the Vorarlberg provincial museum.'' restored on Roman Theatre, Bregenz', '8d6f0cd43c2893f6830dfd01ebe4510e95f45bab2f60b2aeb38ed17451826466|3ff65db44712c6549a3b910ea8290c6cb71736b8ca4fcb2eafd901a0c0313f5c|3ff65db44712c6549a3b910ea8290c6cb71736b8ca4fcb2eafd901a0c0313f5c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the Thalbach quarter of Bregenz lies a Roman Theatre built for more than 2000 visitors, by far more than the town''s population needed in Roman times. It was excavated in 2013 and 2019."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Roman Theatre is in the Thalbach quarter of Bregenz [S1]; it was built for more than 2000 visitors [S3]; that was by far more than the population of Bregenz needed in Roman times [S4]; it was excavated in 2013 and 2019 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The site is a Roman theatre located in the Thalbach quarter of Bregenz, Austria [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Bregenz)]; The theatre was built for more than 2000 visitors [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Bregenz)]; Its capacity was by far more than the population of Bregenz needed in Roman times [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Bregenz)]; Bregenz was a town in Roman times (Roman Brigantium) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Bregenz)]; The theatre was excavated in 2013 and 2019 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Bregenz)]"}]'::jsonb),
    ('2e7960b4-0ff1-49de-9c64-68915cdb824f'::uuid, 'card_description', 'Cripplegate was a gate in the London Wall around the City of London. Rebuilt in the 1490s and fortified with a portcullis after 1660, it was demolished in 1760; only small fragments survive.', 'The northern gate of Roman London''s wall, built 120–150 AD — eighty years before the rest of the wall. The gate predates the wall it later joined.', 'teaser-card-s002-rollback:2e7960b4-0ff1-49de-9c64-68915cdb824f:card_description', 'rollback of teaser-card-s002: card_description "The northern gate of Roman London''s wall, built 120–150 AD — eighty years before the rest of the wall. The gate predates the wall it later joined." restored on Cripplegate', 'e78971177c4363c7b140302a53addd98e86f49378a44a6136d4a2c2daca7a1d9|cffb45d5016ba47db8801ee00ac402b7d2dd04fb96c1312d519adce8cb3fd1fc|cffb45d5016ba47db8801ee00ac402b7d2dd04fb96c1312d519adce8cb3fd1fc', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cripplegate was a gate in the London Wall around the City of London. Rebuilt in the 1490s and fortified with a portcullis after 1660, it was demolished in 1760; only small fragments survive."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cripplegate was a gate in the London Wall [S1]; the wall enclosed the City of London [S1]; it was rebuilt in the 1490s [S3]; it was fortified with a portcullis after 1660 [S3]; it was demolished in 1760 [S4]; only small fragments survive [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cripplegate was a gate in the London Wall [SUPPORTED: https://en.wikipedia.org/wiki/Cripplegate]; The London Wall ran around (enclosed) the City of London [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The gate was rebuilt in the 1490s [SUPPORTED: https://en.wikipedia.org/wiki/Cripplegate]; The gate was fortified with a portcullis after 1660 [SUPPORTED: https://en.wikipedia.org/wiki/Cripplegate]; The gate was demolished in 1760 [SUPPORTED: https://mapoflondon.uvic.ca/CRIP1.htm]; Only small fragments of the gate survive [SUPPORTED: https://en.wikipedia.org/wiki/Cripplegate]"}]'::jsonb),
    ('2e8550b6-1358-471f-9be5-9957b2613c9d'::uuid, 'card_description', 'Its Welsh name means stone house: on the smoothly rounded summit of Mynydd Maendy, a moorland near the former coal mining village of Gilfach Goch, sheep graze beside a wind farm.', 'Mynydd Maendy is located about one mile west of the small, former coal mining village of Gilfach Goch in the County Borough of Rhondda Cynon Taf.', 'teaser-card-s002-rollback:2e8550b6-1358-471f-9be5-9957b2613c9d:card_description', 'rollback of teaser-card-s002: card_description ''Mynydd Maendy is located about one mile west of the small, former coal mining village of Gilfach Goch in the County Borough of Rhondda Cynon Taf.'' restored on Mynydd Maendy', '35b97326fcf2e6316693152b7f3927956bb0fac71ee3b0b17e338b387e1451b6|0f85b14cf5b378d19b06312479166832d917c0ab7bb5eb6f3b812885be9423f0|0f85b14cf5b378d19b06312479166832d917c0ab7bb5eb6f3b812885be9423f0', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Its Welsh name means stone house: on the smoothly rounded summit of Mynydd Maendy, a moorland near the former coal mining village of Gilfach Goch, sheep graze beside a wind farm."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the name derives from Welsh words meaning stone house [S2]; Mynydd Maendy has a smoothly rounded summit [S4]; Mynydd Maendy is a moorland [S1]; it is near Gilfach Goch [S1, S3]; Gilfach Goch is a former coal mining village [S3]; sheep graze on the summit [S4]; a wind farm stands on the summit [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mynydd Maendy is a hilltop moorland in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; Mynydd Maendy lies near Gilfach Goch [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; Its Welsh name means stone house [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; The summit of Mynydd Maendy is smoothly rounded [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; Gilfach Goch is a former coal mining village [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; Sheep graze on the summit [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Maendy]; A wind farm stands on the summit [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Mynydd_Maendy]"}]'::jsonb),
    ('2eae8fd6-d3d4-4764-a8bd-2d3a8f88ebbe'::uuid, 'card_description', 'On the Kacchi Plain near the Bolan Pass, Mehrgarh gave up about 32,000 artefacts, among them a 6,000-year-old wheel-shaped copper amulet, the oldest known example of the lost-wax technique.', 'The oldest known example of the lost-wax technique comes from a 6,000-year-old wheel-shaped copper amulet found at Mehrgarh.', 'teaser-card-s002-rollback:2eae8fd6-d3d4-4764-a8bd-2d3a8f88ebbe:card_description', 'rollback of teaser-card-s002: card_description ''The oldest known example of the lost-wax technique comes from a 6,000-year-old wheel-shaped copper amulet found at Mehrgarh.'' restored on Mehrgarh', 'd870d0ab8903b69f2613717bc7e1d5bb9b6b4ca9d9f0a8e3e3bb53e40aa8d501|7e9948b5331cd415560b6fc7b18f48dd60a241a10a44bd5e9b26e5aa83d23899|7e9948b5331cd415560b6fc7b18f48dd60a241a10a44bd5e9b26e5aa83d23899', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the Kacchi Plain near the Bolan Pass, Mehrgarh gave up about 32,000 artefacts, among them a 6,000-year-old wheel-shaped copper amulet, the oldest known example of the lost-wax technique."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mehrgarh is on the Kacchi Plain [S1]; it is near the Bolan Pass [S2]; about 32,000 artefacts have been collected from the site [S4]; a 6,000-year-old wheel-shaped copper amulet was found there [S6]; the amulet is the oldest known example of the lost-wax technique [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mehrgarh is an archaeological site on the Kacchi Plain (Balochistan, Pakistan) [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; Mehrgarh lies near the Bolan Pass [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; About 32,000 artefacts have come from the site [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; Among the finds is a wheel-shaped amulet [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; The amulet is made of copper [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; The amulet is about 6,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]; The amulet is the oldest known example of the lost-wax technique [SUPPORTED: https://en.wikipedia.org/wiki/Mehrgarh]"}]'::jsonb),
    ('2f0149c1-970a-45cc-b586-c8142970d579'::uuid, 'card_description', 'Most scholars see the City of David as Jerusalem''s original core: Middle Bronze Age defences ring the Gihon Spring, and a Stepped Street ran from the Pool of Siloam to the Temple Mount.', 'The original settlement core of Jerusalem, occupied since 3200 BC. Its water tunnels, including the Pool of Siloam, solved the problem of siege water supply.', 'teaser-card-s002-rollback:2f0149c1-970a-45cc-b586-c8142970d579:card_description', 'rollback of teaser-card-s002: card_description ''The original settlement core of Jerusalem, occupied since 3200 BC. Its water tunnels, including the Pool of Siloam, solved the problem of siege water supply.'' restored on City of David', 'a30a41b1fe0d1879859843dd33a1f2dbcf226666c8bd6a62b95e64e3a2e668b5|764e9e0c3afc8ab611b9bc0ca628597572d5dda1613648a60b66e66400822034|764e9e0c3afc8ab611b9bc0ca628597572d5dda1613648a60b66e66400822034', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Most scholars see the City of David as Jerusalem''s original core: Middle Bronze Age defences ring the Gihon Spring, and a Stepped Street ran from the Pool of Siloam to the Temple Mount."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "most scholars consider the City of David the original settlement core of Jerusalem [S1]; Middle Bronze Age defensive remains surround the Gihon Spring [S2]; a Stepped Street ran from the Pool of Siloam to the Temple Mount [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The City of David is an archaeological site that is Jerusalem''s original settlement core [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]; Most scholars hold this view of the City of David [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]; The site has defences dating to the Middle Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]; These Middle Bronze Age defences ring (surround) the Gihon Spring [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]; The site includes a Stepped Street and the Pool of Siloam [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]; The Stepped Street ran from the Pool of Siloam to the Temple Mount [SUPPORTED: https://en.wikipedia.org/wiki/City_of_David_(archaeological_site)]"}]'::jsonb),
    ('2f68e3c4-6af8-40f0-833e-00602e7fe639'::uuid, 'card_description', 'Partly carved out of the mountain and ringed by cliffs, Geghard Monastery keeps churches dug into the rock, engraved khachkars and a cave spring sacred in pre-Christian times.', 'A medieval monastery with churches and tombs carved directly into the mountainside — the peak of Caucasian rock-cut architecture. Founded in the 4th century.', 'teaser-card-s002-rollback:2f68e3c4-6af8-40f0-833e-00602e7fe639:card_description', 'rollback of teaser-card-s002: card_description ''A medieval monastery with churches and tombs carved directly into the mountainside — the peak of Caucasian rock-cut architecture. Founded in the 4th century.'' restored on Geghard Monastery', '2b828fce7cb64339bc07037c6bf2effc8ea55b13b61feb7ef4695e24fd87189b|ce65f6ce1a89a1d3b158afb6f8073dc068d3f8b248391299783962dcec8c6afc|ce65f6ce1a89a1d3b158afb6f8073dc068d3f8b248391299783962dcec8c6afc', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Partly carved out of the mountain and ringed by cliffs, Geghard Monastery keeps churches dug into the rock, engraved khachkars and a cave spring sacred in pre-Christian times."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Geghard Monastery is partly carved out of the mountain [S1]; it is ringed (surrounded) by cliffs [S1]; it has churches dug into the rock [S2]; it has engraved khachkars [S3]; it has a cave spring that was sacred in pre-Christian times [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Geghard Monastery is a monastery in Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The monastery is partly carved out of the mountain [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The monastery is ringed by cliffs [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The monastery has churches dug into the rock [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The monastery has engraved khachkars [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The monastery has a spring in a cave [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]; The cave spring was sacred in pre-Christian times [SUPPORTED: https://en.wikipedia.org/wiki/Geghard]"}]'::jsonb),
    ('30728ed9-125f-4fba-80de-20fa17d2b02b'::uuid, 'card_description', 'At Kabah, the Palace of the Masks bears hundreds of stone masks of the long-nosed rain god Chaac, and copal incense has been found in some of the rain gods'' stone noses.', 'A Maya city in the Puuc region already inhabited by the 3rd century BC. Most visible architecture is from the 7th-11th centuries, linked to Uxmal by a raised road.', 'teaser-card-s002-rollback:30728ed9-125f-4fba-80de-20fa17d2b02b:card_description', 'rollback of teaser-card-s002: card_description ''A Maya city in the Puuc region already inhabited by the 3rd century BC. Most visible architecture is from the 7th-11th centuries, linked to Uxmal by a raised road.'' restored on Kabah', '99c6bf74080b006620d7dc5fcae24c6123d6b1340a74a7878d55e1d54b8e70cf|8fcc124f46c24a429e8967fbea0152e041bf1863a95258e00ac3e99237bbbc27|8fcc124f46c24a429e8967fbea0152e041bf1863a95258e00ac3e99237bbbc27', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Kabah, the Palace of the Masks bears hundreds of stone masks of the long-nosed rain god Chaac, and copal incense has been found in some of the rain gods'' stone noses."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kabah has a structure called the Palace of the Masks [S4]; the Palace of the Masks bears hundreds of stone masks [S4]; the masks depict the long-nosed rain god Chaac [S4]; copal incense has been found in some of the rain gods'' stone noses [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kabah is an ancient Maya site in Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Kabah]; Kabah has a building called the Palace of the Masks [SUPPORTED: https://en.wikipedia.org/wiki/Kabah_(Maya_site)]; The Palace of the Masks bears hundreds of stone masks [SUPPORTED: https://en.wikipedia.org/wiki/Kabah_(Maya_site)]; The masks depict the long-nosed rain god Chaac [SUPPORTED: https://en.wikipedia.org/wiki/Kabah_(Maya_site)]; Copal incense has been found in some of the rain gods'' stone noses [SUPPORTED: https://en.wikipedia.org/wiki/Kabah_(Maya_site)]"}]'::jsonb),
    ('315b648b-298b-402d-95e6-f0f79249b06f'::uuid, 'card_description', 'On a high ridge above the valley of the Río Negro, Chutixtiox keeps about 30 Maya structures, and on its main plaza a radial pyramid climbs 6.8 metres, a stairway on each side.', 'Ceramic evidence links this Late Postclassic site near Sacapulas to the K''iche'' capital of Q''umarkaj. Its two architectural phases suggest a long-lived settlement rather than a single episode.', 'teaser-card-s002-rollback:315b648b-298b-402d-95e6-f0f79249b06f:card_description', 'rollback of teaser-card-s002: card_description "Ceramic evidence links this Late Postclassic site near Sacapulas to the K''iche'' capital of Q''umarkaj. Its two architectural phases suggest a long-lived settlement rather than a single episode." restored on Chutixtiox', 'cd2c2e71281c4c484bb89169bb7b91c6b061d726124a20a369389c21edb878f2|bf94c798f189e34efc1a6ae95782df4cffbf49e6bc90a500b19402eefda58636|bf94c798f189e34efc1a6ae95782df4cffbf49e6bc90a500b19402eefda58636', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a high ridge above the valley of the Río Negro, Chutixtiox keeps about 30 Maya structures, and on its main plaza a radial pyramid climbs 6.8 metres, a stairway on each side."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Chutixtiox lies on a high ridge [S3]; the ridge is above the valley of the Rio Negro [S4]; the site has about 30 structures [S6]; the structures are Maya [S1]; its main plaza has a radial pyramid [S7]; the pyramid is 6.8 metres tall [S7]; the pyramid has a stairway on each side [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Chutixtiox is an ancient Maya archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/1955_in_archaeology]; Chutixtiox lies on a high ridge [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]; The ridge rises above the valley of the Río Negro [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]; Chutixtiox has about 30 structures [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]; A radial pyramid stands on the main plaza [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]; The radial pyramid is 6.8 metres tall [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]; The radial pyramid has a stairway on each side [SUPPORTED: https://en.wikipedia.org/wiki/Chutixtiox]"}]'::jsonb),
    ('31cb23a8-36ad-4fdc-8fe8-cfca39285d66'::uuid, 'card_description', 'On a limestone ridge at Malta''s southern edge, Ħaġar Qim opens with a trilithon entrance, and its northern temple, the oldest part, holds an oval chamber with an apse on each side.', 'A megalithic temple complex from 3600–3200 BC built of soft Globigerina limestone. Millennia of weathering have severely eroded its surfaces, giving it a melted appearance.', 'teaser-card-s002-rollback:31cb23a8-36ad-4fdc-8fe8-cfca39285d66:card_description', 'rollback of teaser-card-s002: card_description ''A megalithic temple complex from 3600–3200 BC built of soft Globigerina limestone. Millennia of weathering have severely eroded its surfaces, giving it a melted appearance.'' restored on Ħaġar Qim', 'e9f3fce44797eafb6f50744147d5e733b770fa197256b9647d7a30c3e6602b79|a2872bf85122fff9d7b8662898398950d576af102bae52fe058bb4e4be4705c2|a2872bf85122fff9d7b8662898398950d576af102bae52fe058bb4e4be4705c2', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a limestone ridge at Malta''s southern edge, Ħaġar Qim opens with a trilithon entrance, and its northern temple, the oldest part, holds an oval chamber with an apse on each side."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Hagar Qim stands on a limestone ridge [S2]; it is at the southern edge of Malta [S2]; it has a trilithon entrance [S3]; its northern temple is the oldest part [S5]; the northern temple holds an oval chamber [S5]; the chamber has an apse on each side [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Ħaġar Qim is a megalithic temple complex on Malta [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; Ħaġar Qim stands on a limestone ridge [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; Ħaġar Qim is at Malta''s southern edge [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; Ħaġar Qim has a trilithon entrance [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; The northern temple is the oldest part of Ħaġar Qim [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; The northern temple holds an oval chamber [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]; The oval chamber has an apse on each side [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6a%C4%A1ar_Qim]"}]'::jsonb),
    ('3324d203-1f5a-4b13-b6d0-c23382ac8d3c'::uuid, 'card_description', 'Near Duns stands Edin''s Hall Broch, one of very few brochs in southern Scotland, its three cells approximately dumb-bell shaped. In 1976 two copper ingots were apparently found inside.', '28 metres across and unusually large for a southern location, this 2nd-century broch near Duns was once called "Woden''s Hall." Its current name recalls the legend of Red Ettin, the three-headed giant.', 'teaser-card-s002-rollback:3324d203-1f5a-4b13-b6d0-c23382ac8d3c:card_description', 'rollback of teaser-card-s002: card_description ''28 metres across and unusually large for a southern location, this 2nd-century broch near Duns was once called "Woden\''s Hall." Its current name recalls the legend of Red Ettin, the three-headed giant.'' restored on Edin''s Hall Broch', '965bb5af4234c3b3ad94c83c9af8043f3052d262f89ca9b8cc649d549049dbf5|70885fcb7dee08a7ce5efad78d322bdb0c13e401b85e34d757cf6b8e59da42a4|70885fcb7dee08a7ce5efad78d322bdb0c13e401b85e34d757cf6b8e59da42a4', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near Duns stands Edin''s Hall Broch, one of very few brochs in southern Scotland, its three cells approximately dumb-bell shaped. In 1976 two copper ingots were apparently found inside."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Edin''s Hall Broch is near Duns [S1]; it is one of very few brochs in southern Scotland [S2]; it has three cells [S5]; the cells are approximately dumb-bell shaped [S5]; in 1976 two copper ingots were apparently found inside [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Edin''s Hall Broch is a broch in Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; Edin''s Hall Broch stands near Duns [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; It is one of very few brochs in southern Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; The broch has three cells [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; The cells are approximately dumb-bell shaped [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; Two copper ingots were found in 1976 [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]; The copper ingots were apparently found inside the broch [SUPPORTED: https://en.wikipedia.org/wiki/Edin%27s_Hall_Broch]"}]'::jsonb),
    ('337268d6-ceda-4830-914f-cd6782010223'::uuid, 'card_description', 'Atop Knolls Down in Wiltshire, 254m up, the Iron Age hillfort of Fosbury Camp encloses an oval of approximately 26 acres, guarded to the south and east by very steep slopes.', 'An oval Iron Age bivallate hillfort covering 10.5 hectares with steep natural slopes on three sides. The double-banked defenses concentrated on the vulnerable north side.', 'teaser-card-s002-rollback:337268d6-ceda-4830-914f-cd6782010223:card_description', 'rollback of teaser-card-s002: card_description ''An oval Iron Age bivallate hillfort covering 10.5 hectares with steep natural slopes on three sides. The double-banked defenses concentrated on the vulnerable north side.'' restored on Fosbury Camp', '3a09115ecfdac934056975e06564229c2bf5e7f4c2ef321c2337b09932669255|e052b910b3da0649d06ef973ba6f04c81e5c757f9c8f8de3d65719effdc37664|e052b910b3da0649d06ef973ba6f04c81e5c757f9c8f8de3d65719effdc37664', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Atop Knolls Down in Wiltshire, 254m up, the Iron Age hillfort of Fosbury Camp encloses an oval of approximately 26 acres, guarded to the south and east by very steep slopes."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Fosbury Camp is atop Knolls Down [S3]; it is in Wiltshire [S1, S6]; it lies 254 m up [S7]; it is an Iron Age hillfort [S1]; it is oval [S2]; it covers approximately 26 acres [S2]; it is guarded to the south and east by very steep slopes [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Fosbury Camp is an Iron Age hillfort in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; The hillfort sits atop Knolls Down [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; It lies 254 m up (above sea level) [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; The enclosure is oval in shape [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; It encloses approximately 26 acres [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; It is guarded to the south by very steep slopes [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]; It is guarded to the east by very steep slopes [SUPPORTED: https://en.wikipedia.org/wiki/Fosbury_Camp]"}]'::jsonb),
    ('33ac2b60-4a42-4331-9c91-93388429ada0'::uuid, 'card_description', 'From Gandahara in the Kushan period, the Sikri Stupa tells of the life of Buddha in 13 narrative panels. Three photos taken around 1890 show their order in the earliest restoration.', 'A 3rd–4th century AD Kushan Buddhist stupa with 13 narrative panels of Buddha''s life. Modern restoration arranged the panels in their original sequence.', 'teaser-card-s002-rollback:33ac2b60-4a42-4331-9c91-93388429ada0:card_description', 'rollback of teaser-card-s002: card_description "A 3rd–4th century AD Kushan Buddhist stupa with 13 narrative panels of Buddha''s life. Modern restoration arranged the panels in their original sequence." restored on Sikri Stupa', 'a7e08ffe43874a0547fc0763be8c9fd53533f502490069a60d503594cebf3af6|39c663708638f8550c5f1ebbe9de2f20bc469cecfb9a4956c48de3af481b3239|39c663708638f8550c5f1ebbe9de2f20bc469cecfb9a4956c48de3af481b3239', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "From Gandahara in the Kushan period, the Sikri Stupa tells of the life of Buddha in 13 narrative panels. Three photos taken around 1890 show their order in the earliest restoration."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Sikri Stupa is from Gandahara [S1]; it dates from the Kushan period [S1]; it depicts the life of Buddha [S1]; it has 13 narrative panels [S1]; three photos taken around 1890 show the panels'' order in the earliest restoration [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Sikri Stupa is a Buddhist stupa (a work of Buddhist art) from Gandhara (Gandahara) [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; It dates from the Kushan period [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; It tells of the life of Buddha [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; It has 13 narrative panels [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; Three photos exist of the panels [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; The photos were taken around 1890 [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]; The photos show the order of the panels in the earliest restoration [SUPPORTED: https://en.wikipedia.org/wiki/Sikri_Stupa]"}]'::jsonb),
    ('348770cd-a3a2-4b6e-83f7-bd5f5d699022'::uuid, 'card_description', 'On a Breton peninsula rises Barnenez, a Neolithic cairn 72 m long built of 13,000 to 14,000 tons of stone. Separate passages lead to its 11 chambers, some engraved with symbols.', 'Radiocarbon dates indicate that the first phase of the monument was erected between 4850 and 4250 BC, and the second phase between 4450 and 4000 BC.', 'teaser-card-s002-rollback:348770cd-a3a2-4b6e-83f7-bd5f5d699022:card_description', 'rollback of teaser-card-s002: card_description ''Radiocarbon dates indicate that the first phase of the monument was erected between 4850 and 4250 BC, and the second phase between 4450 and 4000 BC.'' restored on Barnenez', '37d1cb1106747dc5f35e41bbdb5757709f3fbd5bb648377bf45f24b3b8b79162|2311ba14fcc08e2b256b5fa80d666ad1148331bb7d8afaf2945633c54ee49147|2311ba14fcc08e2b256b5fa80d666ad1148331bb7d8afaf2945633c54ee49147', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a Breton peninsula rises Barnenez, a Neolithic cairn 72 m long built of 13,000 to 14,000 tons of stone. Separate passages lead to its 11 chambers, some engraved with symbols."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Barnenez is on a Breton peninsula [S1]; it is a Neolithic cairn [S1]; it is 72 m long [S3]; it is built of 13,000 to 14,000 tons of stone [S4]; separate passages lead to its chambers [S5]; it has 11 chambers [S5]; some chambers are engraved with symbols [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Barnenez is a Neolithic cairn (monument) in Brittany [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; It stands on a peninsula in Brittany [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; The cairn is 72 m long [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; It is built of 13,000 to 14,000 tons of stone [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; It contains 11 chambers [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; The chambers are reached by separate passages [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]; Some of the chambers are engraved with symbols [SUPPORTED: https://en.wikipedia.org/wiki/Barnenez]"}]'::jsonb),
    ('34bbe345-3a0c-4b09-a81b-23ada293da19'::uuid, 'card_description', 'At the Anta da Estria, a megalithic dolmen believed to date to 4000-2500 BC, Carlos Ribeiro identified nine raised slabs but no stones that could have formed a roof.', 'The Anta da Estria, the Anta do Monte Abraão and the Anta da Pedra dos Mouros are collectively known as the Antas de Belas, and were first identified in the 1870s by Carlos Ribeiro.', 'teaser-card-s002-rollback:34bbe345-3a0c-4b09-a81b-23ada293da19:card_description', 'rollback of teaser-card-s002: card_description ''The Anta da Estria, the Anta do Monte Abraão and the Anta da Pedra dos Mouros are collectively known as the Antas de Belas, and were first identified in the 1870s by Carlos Ribeiro.'' restored on Anta da Estria', '48dd3307f9a3b554d160c041a5086278eec185b70d35ac551675b975f630450f|e609aeeeb0cf1e38f0453603cc95ab170bfee65c13fbe67c4c95f46b430e5769|e609aeeeb0cf1e38f0453603cc95ab170bfee65c13fbe67c4c95f46b430e5769', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At the Anta da Estria, a megalithic dolmen believed to date to 4000-2500 BC, Carlos Ribeiro identified nine raised slabs but no stones that could have formed a roof."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Anta da Estria is a megalithic dolmen [S1]; it is believed to date to 4000-2500 BC [S2]; Carlos Ribeiro identified nine raised slabs [S5]; Ribeiro identified no stones that could have formed a roof [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Anta da Estria is a megalithic dolmen (in Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Estria]; It is believed to date to 4000-2500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Estria]; Carlos Ribeiro investigated the dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Estria]; Carlos Ribeiro identified nine raised slabs [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Estria]; Ribeiro identified no stones that could have formed a roof [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Estria]"}]'::jsonb),
    ('34c9266e-b55c-4f29-9e6e-eeb547ecfd50'::uuid, 'card_description', 'On a steep rocky plateau of Skye above a fertile valley and the sea, the Iron Age broch of Dun Hallin still stands up to 3.8 metres, oval guard cells flanking its entrance passage.', 'Dun Hallin is an Iron Age broch located near the northwest coast of the island of Skye.', 'teaser-card-s002-rollback:34c9266e-b55c-4f29-9e6e-eeb547ecfd50:card_description', 'rollback of teaser-card-s002: card_description ''Dun Hallin is an Iron Age broch located near the northwest coast of the island of Skye.'' restored on Dun Hallin', '7473759ec281dc3f5a3a4bd47cbe00252fba8259a1a6f4f27182a149cd78c9e5|e5bec80b1a28a9a6ce977629bcbe4a00655aa9e4849491d14658eef930e27e01|e5bec80b1a28a9a6ce977629bcbe4a00655aa9e4849491d14658eef930e27e01', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a steep rocky plateau of Skye above a fertile valley and the sea, the Iron Age broch of Dun Hallin still stands up to 3.8 metres, oval guard cells flanking its entrance passage."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Dun Hallin is on a steep rocky plateau [S3]; it is on Skye [S1, S2]; the plateau overlooks a fertile valley and the sea [S3]; it is an Iron Age broch [S1]; its walls still stand up to 3.8 metres [S5]; oval guard cells flank its entrance passage [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Dun Hallin is an Iron Age broch on the Isle of Skye [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]; It stands on a steep rocky plateau [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]; The plateau is above a fertile valley [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]; The plateau is above the sea [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]; The broch still stands up to 3.8 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]; Oval guard cells flank its entrance passage [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Hallin]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s002-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s002-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s002-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'card_description', 'Rivers wrap Burnt Fen on three sides: low-lying prime farmland between Littleport and Mildenhall, where a remarkable amount of Mesolithic archaeology has come to light.'), ('0151be4b-c7d5-487f-8844-27e110594270'::uuid, 'card_description', 'Beside the Roman road to Sawley on the River Trent, 600m east of the Derventio fort in Little Chester, lies the Derby Racecourse Roman Settlement, founded around AD 90.'), ('019ea3e7-663b-4a60-863a-980007df6878'::uuid, 'card_description', 'Modelled after Djoser''s step pyramid, the Pyramid of Sekhemkhet at Saqqara held a sarcophagus cut from a single block of fine alabaster, its lid slid into place and sealed with mortar.'), ('0248e2bc-e43e-4bb6-8435-b9f9cac52040'::uuid, 'card_description', 'Cyrus the Great founded Pasargadae near where he defeated Astyages. Its ruins hold a mausoleum commonly believed to be his, a fortress on a hill and the earliest known fourfold garden.'), ('028deb2a-ddfb-43d8-94bf-e8f64a6e21da'::uuid, 'card_description', 'On a hilltop west of Newcastle stood Condercum, third fort on Hadrian''s Wall, built between 122 and 124 AD. A hundred yards east, the remains of a temple to Antenociticus can still be seen.'), ('02941d88-16e9-42c6-8abf-e7d5b5b38821'::uuid, 'card_description', 'Above Bath and the River Avon, the limestone plateau of Bathampton Down has yielded Mesolithic flints, and holds four reported Bronze Age barrows and an Iron Age hillfort or stock enclosure.'), ('02c083c6-8552-4edb-8b3d-26d649280de5'::uuid, 'card_description', 'At Apadana Castle Shush stood the Palace of Darius in Susa, where the Persian column topped by two bulls was probably developed. Once destroyed by fire and partly restored, little remains.'), ('033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe'::uuid, 'card_description', 'Where the Sava meets the Danube stands the Belgrade Fortress. The Celtic Scordisci founded Singidunum here in the 3rd century BC; Goths and Huns later repeatedly destroyed its Roman camp.'), ('038e5559-6e30-4520-ad95-4ba9679b24a6'::uuid, 'card_description', 'Where the Altmühl meets the Danube, on a peninsula inhabited more or less constantly since 13,000 BCE, the Celtic oppidum of Alcimoennis crowned the Michelsberg hill above Kelheim.'), ('041049ae-edd9-49a3-8233-1ea9b3382913'::uuid, 'card_description', 'For a few decades after the Roman invasion of 43 AD, the Fosse Way marked Rome''s western frontier. For 182 miles, Lincoln to Ilchester, it never strays over 6 miles from a straight line.'), ('042c8c7f-1ec1-485a-ba0b-3ab847320ee7'::uuid, 'card_description', 'From the Maya palace of Labna, approximately 120 m long, a ceremonial road leads to an elaborately decorated arch: not an entrance to the city, but a passage between its public areas.'), ('0490ef6d-5381-449d-aa8c-385ab7dbd8e7'::uuid, 'card_description', 'On Gozo, the walls of the Xagħra Stone Circle enclosed burial caves of the community that built nearby Ġgantija temple. Its dead were dismembered, their body parts buried in separate places.'), ('04b79866-b13b-4b76-ae03-6392651eecab'::uuid, 'card_description', 'At the summit of a lava dome, around 1,435 meters up, the Temple of Mercury rose in trachyte in the 2nd century, replacing a temple apparently too small for the many pilgrims who came.'), ('05133e1e-6d12-461c-a682-d8ac77d2550f'::uuid, 'card_description', 'Near Goni, around sixty menhirs stand in pairs, alignments and groups at the Necropolis of Pranu Muttedu, beside funerary chambers once covered by a tumulus and ringed by megalithic circles.'), ('06f66762-c2a9-465c-bc9e-a31052ec7ce6'::uuid, 'card_description', 'On the way to the Acropolis of Athens, the Roman Beulé Gate was built almost entirely from the Choragic Monument of Nikias, whose dedicatory inscription still shows in its entablature.'), ('0849cdd5-5b9a-40c2-9aa9-f58c1ac32b22'::uuid, 'card_description', 'In 1900 Harriet Boyd found 13 rooms on Kavousi Kastro and took them for an early chieftain''s house. Now they read as separate homes on the terraces of a Greek Dark Ages refuge.'), ('086aa9b8-6e6e-492d-baf2-a829b5eb0f6c'::uuid, 'card_description', 'On a small hill above the Aln valley, Jenny''s Lantern keeps an Iron Age hillfort and the remains of at least 15 stone-founded circular huts. A lacrymatory was found here in 1824.'), ('08882f84-f34c-4930-b595-ef7e46a6916d'::uuid, 'card_description', 'On an isolated hilltop in Exmoor, the Iron Age hillfort of Cow Castle commands the valley of the River Barle behind a single rampart and ditch. What threatens it now is bracken.'), ('093a4419-157b-4562-8da5-6be601aabc2d'::uuid, 'card_description', 'On a ridge 3480 meters up, Raqch''i was a control point on the Inca road system from Cusco. Its Temple of Wiracocha, the biggest kallanka of the Inca Empire, stands by 152 round qullqas.'), ('097bd79b-a0d9-40d1-832d-c8a0671f7ab3'::uuid, 'card_description', 'Next to Bhir Mound, just south of Sirkap in the Taxila area, lies Hathial, quite a large ancient site. The red burnished ware and other materials found here resemble those of Charsadda.'), ('0a7b9508-615a-47ac-8044-abdae7a7401b'::uuid, 'card_description', 'The Roman road Dere Street ran north from York across Hadrian''s Wall into what is now Scotland. At Dun Law it was laid over a palaeochannel on a lattice of logs and a mat of branchwood.'), ('0abf05cb-0fda-4567-9d9d-0829911a8c66'::uuid, 'card_description', 'In 1963 two students found Paradise Cave inside Malik hill, south of Kielce. Its cave deposits hold traces of Neanderthal occupancy from the late Pleistocene, 50 to 60 thousand years ago.'), ('0b34fdec-f221-40f9-8238-2d78d7ce6638'::uuid, 'card_description', 'Southwest of Larissa, Cranon was a walled city of ancient Thessaly that minted silver coins, yet almost nothing is known of its acropolis, save a possible temple of Athena Polias.'), ('0b681115-78b6-409f-b780-4330392e5b40'::uuid, 'card_description', 'The springs of the Roman Baths were dedicated to the goddess Sulis, perhaps at a Celtic centre of worship. A temple rose here between 60 and 70 AD; the baths grew over the next 300 years.'), ('0b994bf5-92ed-4592-a7f7-1a3d343cefd6'::uuid, 'card_description', 'In Saumur, the Dolmen de Bagneux is the largest dolmen in France, its sandstone chamber stretching 17.3 metres. Likely Neolithic, circa 3000 BC, it would have received many burials.'), ('0cd2e708-f7f6-412d-91ba-6d00420b5056'::uuid, 'card_description', 'Locals call it Hetty Pegler''s Tump: Uley Long Barrow, a Neolithic burial mound probably built before 3000 BC. An excavation in 1821 revealed the remains of fifteen skeletons within.'), ('0d2486f1-4650-4c10-9f4c-b25a3e345012'::uuid, 'card_description', 'Nim Li Punit is Kekchi Maya for Big Hat, after the elaborate head-dress of an ancient king on a stela found here. Life around its three plazas ceased rather suddenly in the 9th century AD.'), ('0ea92399-96d7-4b98-839f-5ac77983e576'::uuid, 'card_description', 'On the Acropolis, 23 m east of the Parthenon, the Temple of Roma and Augustus rose circa 19 BCE: a marble ring of nine columns with no interior wall, a propaganda monument of Rome.'), ('0eec5ffa-1383-4b6b-92d1-cdc1f1dc0cfb'::uuid, 'card_description', 'Inside Densuș Church, the oldest Orthodox stone church in Romania, 15th-century murals by the artist Ștefan show Jesus in traditional Romanian clothes. From 1566 it served Calvinists too.'), ('0f2a7448-cb04-4aee-90b5-deb59d72647f'::uuid, 'card_description', 'Two ditches form the perimeter of Castle Dore, an Iron Age hill fort near Golant. Digging inside it from 1936, Ralegh Radford found postholes of huts from at least two phases of occupation.'), ('0f785541-1f36-4dc8-9daa-3ebc5c540bd0'::uuid, 'card_description', 'South of the River Swale stood Cataractonium, a Roman fort where the road north from Eboracum split in two. Among its finds lay a theatrical mask, hinting at a possible theatre.'), ('0f8924db-4ea5-4e63-88f5-866f06bb2248'::uuid, 'card_description', 'An 8 metre corridor led into the Anta do Monte Abraão, a Neolithic dolmen that excavations suggest was a tomb for about 80 individuals. Its finds include flint arrowheads and stone axes.'), ('1032047c-3a0c-413b-bd70-23b81f64487e'::uuid, 'card_description', 'Across a ridge of Dartmoor, Shovel Down holds stone rows of probable Bronze Age date and the Fourfold Circle, four concentric stone circles where a turf-covered cairn keeps a robbed cist.'), ('115be95f-85b1-472e-86b4-e68c8f55bdd5'::uuid, 'card_description', 'At Vindolanda, just south of Hadrian''s Wall, Roman forts were built one on top of the other. Its wooden tablets were, when found, the oldest surviving handwritten documents in Britain.'), ('116de084-cd63-4ec0-aeca-4702b91b1bdb'::uuid, 'card_description', 'The Military Road now cuts through Hunnum, the fifth fort on Hadrian''s Wall, built between 122 and 126 AD. A slab from its west gate names the Legio VI Victrix as its first builders.'), ('120f7321-78f7-4786-a3a3-13d6b3c9d0f6'::uuid, 'card_description', 'Near Kazanlak, a corridor 13 metres long leads into the three spacious rooms of the Tomb of Seuthes III, a temple of the 5th century BC where the Thracian king was buried around 300 BC.'), ('13b5bbe7-ff6b-4a1e-a8f5-d17ed3fee4f6'::uuid, 'card_description', 'On the sea lay Gnatia, a frontier town of the Messapii famed for a solar and fire cult that Pliny described and Horace ridiculed. It is famous for the discoveries made in its tombs.'), ('142c0275-1a5c-47dd-a562-c6874cafa728'::uuid, 'card_description', 'On a high point by the Ridgeway, the hillfort of Liddington Castle hides a pit at least 2.4 metres deep. Its diggers did not reach the bottom, and they interpreted it as a ritual shaft.'), ('14aacb74-9cd3-4766-b74b-4911d804c415'::uuid, 'card_description', 'Cattle from North Wales were driven along the Welsh Road to markets in South East England. Its age is not known, yet many lengths follow parish boundaries, hinting at a pre-Roman trackway.'), ('1567cad6-7871-428a-b923-946a24ef9b8d'::uuid, 'card_description', 'Where did Krimisa stand? Scholars lean towards Punta Alice, near Cirò Marina, for this town of an indigenous people assimilated by the Greeks, probably born in the 7th century BC.'), ('16d9eae9-81b1-436e-bd93-e6aea4b4c818'::uuid, 'card_description', 'Samicum stood on a spur of a lofty mountain that leaves only a narrow pass by the coast. Nearby, a grove of wild olives surrounded a celebrated temple of the Samian Poseidon.'), ('16e413ef-7b76-4fda-8f07-5cecf817071d'::uuid, 'card_description', 'In 1949 a woman''s grave of the Roman Iron Age was found at Gårdlösa, a silver fibula with a runic inscription inside. Later digs explored house foundations, grave fields and a shrine.'), ('17a5dcfe-4f54-467a-9399-ce1a6c72f267'::uuid, 'card_description', 'Outside the walls of Roman Melite, St. Paul''s Catacombs spread through underground galleries and tombs, where tables hewn from the living rock held meals commemorating dead relatives.'), ('186ef9b5-7a74-43d6-b8d3-f49357ea1304'::uuid, 'card_description', 'Begun under Trajan, the Amphitheatre of Durrës could once hold 20,000 people, the largest Roman amphitheatre ever built in the Balkan Peninsula. A Christian chapel later rose on it.'), ('190fdea4-2036-47fa-a6ca-81b3b0ab2e93'::uuid, 'card_description', 'Where an open valley near Lagos begins to narrow lies the Roman Dam of Fonte Coberta: a straight wall of rectangular section, raised during the Romanization of Hispania.'), ('197dd3af-e63a-48fc-80a1-ed694a5629fc'::uuid, 'card_description', 'Near Västerås rises Anundshög, the largest tumulus in Sweden. At its foot, 2 large stone ships lie end to end, one of them 51 metres long, on what was once a thing-place.'), ('19f1118c-190f-47f7-a161-8d6cd52277e7'::uuid, 'card_description', 'Two holes left by a collapse of undetermined date open the roof of Vela Spila Cave. Here lay 36 ceramic artifacts, the only Upper Palaeolithic ceramic figurative art in southeastern Europe.'), ('1a26d6f1-d77a-4bb4-a018-afb806a4cd15'::uuid, 'card_description', 'In 1966, 300 meters from the Playa de El Rinconcillo in Algeciras, the Roman Kilns of El Rinconcillo came to light: two furnaces joined as one, vaults resting on a column and eight arches.'), ('1a9242d4-250f-4ffb-8dad-dae849c10798'::uuid, 'card_description', 'Near Chichen Itza, Balankanche Cave has drawn rituals to the Maya rain god Chaac for more than two thousand years. Inside were found stairs, altars and ritual displays of ceramics.'), ('1b82a32d-cf01-4735-94c2-7df578796ce5'::uuid, 'card_description', 'In the Kherlen River basin, the Khitan built Bars-Hot, a city 1.6 by 1.8 kilometres ringed with mud walls. Near them a ruined octagonal brick pagoda of the 11th century has lost its top.'), ('1bc57ad9-041a-42de-b0a1-c361a7beb531'::uuid, 'card_description', 'Picture ancient Greek athletes competing in the stadion: the Stadium at Nemea, in Corinthia, was built 400 m southeast of the Temple of Zeus on the ancient site of Nemea.'), ('1c18de52-3783-41cb-a3dd-ade50498a974'::uuid, 'card_description', 'In the Wiehen Hills, 255.6 metres above sea level, the Babilonie hillfort of the La Tène culture encloses over 12 hectares, where ceramics of the Saxon-Frankish period have also turned up.'), ('1c899f53-4414-4954-821d-9119802aa39a'::uuid, 'card_description', 'At the mouth of the Lao River lay Laüs, where Herodotus says survivors of Sybaris, destroyed in 510 BC, took refuge. A tomb found by accident held red-figured vases and bronze armour.'), ('1d7c880b-80be-41b1-8be5-58d07a0e5dcd'::uuid, 'card_description', 'Remote even today, Naachtun was named by Sylvanus Morley after a Mayan phrase glossed as distant stones. Its ancient name was Masuul, and 45 stelae have been excavated among its ruins.'), ('1d873464-bd56-415a-984e-67026294d00c'::uuid, 'card_description', 'On a small headland of North Ronaldsay, the Iron Age Broch of Burrian gave up painted pebbles, part of an iron bell of Celtic type and a cross-slab with an ogham inscription.'), ('1e7ec452-34c4-4630-ac4e-e53d0dcbd184'::uuid, 'card_description', 'Near Takht-i-Bahi lies Seri Bahlol, on the UNESCO World Heritage List since 1980, its relics associated with Buddha not yet properly excavated. Statues and coins are commonly found.'), ('1ed00cd4-fec4-406f-af91-8c6bf79eeb3d'::uuid, 'card_description', 'In southern Corsica, the menhirs of Filitosa were raised around 1500 BC, 2-3 metres tall and carved with human faces, armour and weapons. Arrow heads and pottery trace life here to 3300 BC.'), ('1ef25b31-5c42-4ee6-aae1-1bd9c2640bff'::uuid, 'card_description', NULL), ('1f020df7-29e0-4b61-aecc-80e294e7b59d'::uuid, 'card_description', 'Occupied for more than 2,500 years, the Maya city of Izamal was built of megalithic carved blocks with rounded corners, later a site of pilgrimage rivaled in the region only by Chichen Itza.'), ('1fd1292d-5dbf-4bbf-a501-6a0e094da785'::uuid, 'card_description', 'On the Peneus near Larissa lay Argura, the Argissa of Homer''s Iliad. Its walls with square towers date to the 5th and 4th centuries BCE, and dedications honour Apollo Pythius and Artemis.'), ('20a18387-7871-456c-967a-c94abd69e3e0'::uuid, 'card_description', 'Seuthopolis, seat of the Thracian king Seuthes III and his court, was founded between 325–315 BC. In its cemetery, brick tholos tombs held the upper class, sometimes with their horses.'), ('21660e33-c3b7-462f-aaec-cbaded7b4a8d'::uuid, 'card_description', 'Armazi, original capital of the early Georgian kingdom of Kartli, had ready access to the Daryal Pass, the main road over the Greater Caucasus. The Arab invasion of the 730s destroyed it.'), ('21a181ef-2027-4c76-a8a4-3e59a0b1e51b'::uuid, 'card_description', 'On Souvloto Mouri, a hilltop in eastern Crete with no wells or springs, Chamaizi holds the only known oval-shaped Minoan building, centred on a cistern that likely caught the rain.'), ('21f3da5f-262c-46e8-bead-32be438da097'::uuid, 'card_description', 'On the border of Mesoamerica lies Los Naranjos Archaeological Park. In 1935 Frans Blom and Jens Yde excavated a large mound here and found a large collection of polychrome pottery.'), ('22415177-5658-4973-ab15-ddad22663cde'::uuid, 'card_description', 'Archaeologists estimate over 130 million adobe bricks went into the Huaca del Sol, a Moche pyramid. In the early 17th century, colonists turned the Moche River past its base to loot gold.'), ('23ee2849-5bee-4742-91b1-29a35361fcf7'::uuid, 'card_description', 'Badgers were damaging Barrow Clump, an early Bronze Age bowl barrow in Wiltshire. Digging uncovered many Saxon graves and a bucket-shaped drinking vessel of yew wood bound with bronze.'), ('24f1c052-5bc8-490e-9b1e-ccce0c05611b'::uuid, 'card_description', 'In 627, Bede tells, Bishop Paulinus accompanied King Edwin and Queen Æthelburg to their royal vill at Yeavering, on a terrace below the Iron Age hillfort that crowned Yeavering Bell.'), ('251201f8-0dae-473d-916d-4a7e5c1a970f'::uuid, 'card_description', 'Atop a steep hill, the Dacian Fortress of Căpâlna guarded the way from the Sebeș Valley to the Dacian capital, Sarmizegetusa Regia. Around 106 AD the Romans burnt and destroyed it.'), ('251ac618-a557-4c31-9129-65afc47b649d'::uuid, 'card_description', 'Fleeing Thurii, where fellow colonists killed most of them, Sybarites founded Sybaris on the Traeis, by the river now called the Trionto. Diodorus Siculus writes the Bruttii destroyed it.'), ('257ce429-7d0c-4444-8ed5-57d129c25d50'::uuid, 'card_description', 'On Schanzenkopf, a wooded hill in the Spessart on the Hesse border, lie the remains of a circular rampart up to 12 m wide and 2 to 4 m high, generally attributed to the Hallstatt period.'), ('262b6a28-de86-4e63-bdba-398a67236618'::uuid, 'card_description', 'On Dartmoor, Brisworthy Stone Circle keeps 24 broad, low stones in a slight oval, probably only half the original number. A trial dig is said to have yielded charcoal and one flint flake.'), ('264ac74e-f5bc-4b73-b28a-c2db99132c50'::uuid, 'card_description', 'Wednesbury, Woden''s borough, is named after the pre-Christian god Woden. A large ditch dug up in 2008 is read as part of a hilltop enclosure, possibly the long suspected Iron Age hillfort.'), ('2655cac3-4a76-4ea5-bc1e-9922ce8c08c7'::uuid, 'card_description', 'Once in the wall of an Inca palace, the perfectly cut, finely finished diorite of the Twelve-Angled Stone now sits in the Hatun Rumiyoc, the outer wall of the Archbishop''s palace in Cusco.'), ('26c567ca-9af0-486b-9599-dcb0b7792628'::uuid, 'card_description', 'The Anakeion was the Athens temple of Castor and Pollux, twin sons of Zeus. Pausanias says Mikon depicted the Argonauts there, and Polygnotos the twins seizing the daughters of Leukippos.'), ('27d651ad-32dc-4bbc-bbb9-9218d9aec357'::uuid, 'card_description', 'Near Black Dog in Devon, Berry Castle, an earthwork probably of the Iron Age, breaks the hill fort pattern: a seemingly incomplete enclosure on the slope of a hill that peaks at 199 metres.'), ('280f2b7d-4978-4352-896d-bcbb03837d3e'::uuid, 'card_description', 'At the lake Pumaqucha, in the Vischongo District of Ayacucho, lies Inti Watana, an archaeological site that Peru declared a National Cultural Heritage on July 27, 2001.'), ('2817ce5e-3b43-445e-9a10-d4115a7036bb'::uuid, 'card_description', 'On the Ebro''s west bank, Late Bronze Age cottages grew into the First Iron Age streets of Barranc de Gàfols: at least 17 households, a fireplace in each, and one building with stone mills.'), ('285feaf7-cf87-443a-bfeb-a8e7607a1e91'::uuid, 'card_description', 'Behind Ashdown Park lies Alfred''s Castle, a small Iron Age hill fort begun in the 6th century BC amid late Bronze Age ditches. In the late 1st century a Romano-British farmhouse rose inside.'), ('28b1639a-d35e-4fef-bfac-78dbb00a1d69'::uuid, 'card_description', 'Over a slate gorge of the Erges, Segura Bridge links Portugal to Spanish Alcántara. Only the arches by the banks are Roman, yet the 1571 stonework is deemed barely distinguishable from them.'), ('29446177-8f7d-4e23-9a9c-6c9ba2959472'::uuid, 'card_description', 'South of the Cuillin hills on Skye, on an uninhabited headland whose name means point of the little fort, lies Rubha an Dùnain Passage Grave, amid sites from the Mesolithic onwards.'), ('294968f3-036b-44ff-b704-91593648927d'::uuid, 'card_description', 'On a rocky promontory in northern Kea, Kephala was a Final Neolithic settlement of small rectangular rooms, home perhaps to 45-80 people, recently dated to about 4600-4500 BC.'), ('2968fd35-9b61-4dfb-bb1b-cc4489827fd6'::uuid, 'card_description', 'Its Quechua name means big settlement: Hatunmarka, also spelled Hatunmarca, is an archaeological site in the Jauja Province of Junín, declared a National Cultural Heritage in November 2000.'), ('296ed0f4-1ad0-4929-b019-196c80e547be'::uuid, 'card_description', 'Just outside Hemet, in Reinhardt Canyon within the Lakeview Mountains, lies the Hemet Maze Stone, a prehistoric petroglyph whose stone and land became a California state landmark in 1956.'), ('29d6fc00-4e39-4707-bea6-237454b055fb'::uuid, 'card_description', 'Near Turgut stood Lagina, with a monumental temple of Hecate where great festivals were celebrated every year. Little is known of its early days, though it existed by the 4th century BCE.'), ('2a87862a-98dc-4cbd-8d8e-89f7c1368e63'::uuid, 'card_description', 'On Anglesey, near the Afon Braint, Caer Lêb lies within a double row of pentangular banks and marshy ditches. Its name means Leaven Castle, and under a layer of peat lay periwinkle shells.'), ('2d76f228-e78d-4e1a-934e-cf8eef944e37'::uuid, 'card_description', 'In the Thalbach quarter of Bregenz lies a Roman Theatre built for more than 2000 visitors, by far more than the town''s population needed in Roman times. It was excavated in 2013 and 2019.'), ('2e7960b4-0ff1-49de-9c64-68915cdb824f'::uuid, 'card_description', 'Cripplegate was a gate in the London Wall around the City of London. Rebuilt in the 1490s and fortified with a portcullis after 1660, it was demolished in 1760; only small fragments survive.'), ('2e8550b6-1358-471f-9be5-9957b2613c9d'::uuid, 'card_description', 'Its Welsh name means stone house: on the smoothly rounded summit of Mynydd Maendy, a moorland near the former coal mining village of Gilfach Goch, sheep graze beside a wind farm.'), ('2eae8fd6-d3d4-4764-a8bd-2d3a8f88ebbe'::uuid, 'card_description', 'On the Kacchi Plain near the Bolan Pass, Mehrgarh gave up about 32,000 artefacts, among them a 6,000-year-old wheel-shaped copper amulet, the oldest known example of the lost-wax technique.'), ('2f0149c1-970a-45cc-b586-c8142970d579'::uuid, 'card_description', 'Most scholars see the City of David as Jerusalem''s original core: Middle Bronze Age defences ring the Gihon Spring, and a Stepped Street ran from the Pool of Siloam to the Temple Mount.'), ('2f68e3c4-6af8-40f0-833e-00602e7fe639'::uuid, 'card_description', 'Partly carved out of the mountain and ringed by cliffs, Geghard Monastery keeps churches dug into the rock, engraved khachkars and a cave spring sacred in pre-Christian times.'), ('30728ed9-125f-4fba-80de-20fa17d2b02b'::uuid, 'card_description', 'At Kabah, the Palace of the Masks bears hundreds of stone masks of the long-nosed rain god Chaac, and copal incense has been found in some of the rain gods'' stone noses.'), ('315b648b-298b-402d-95e6-f0f79249b06f'::uuid, 'card_description', 'On a high ridge above the valley of the Río Negro, Chutixtiox keeps about 30 Maya structures, and on its main plaza a radial pyramid climbs 6.8 metres, a stairway on each side.'), ('31cb23a8-36ad-4fdc-8fe8-cfca39285d66'::uuid, 'card_description', 'On a limestone ridge at Malta''s southern edge, Ħaġar Qim opens with a trilithon entrance, and its northern temple, the oldest part, holds an oval chamber with an apse on each side.'), ('3324d203-1f5a-4b13-b6d0-c23382ac8d3c'::uuid, 'card_description', 'Near Duns stands Edin''s Hall Broch, one of very few brochs in southern Scotland, its three cells approximately dumb-bell shaped. In 1976 two copper ingots were apparently found inside.'), ('337268d6-ceda-4830-914f-cd6782010223'::uuid, 'card_description', 'Atop Knolls Down in Wiltshire, 254m up, the Iron Age hillfort of Fosbury Camp encloses an oval of approximately 26 acres, guarded to the south and east by very steep slopes.'), ('33ac2b60-4a42-4331-9c91-93388429ada0'::uuid, 'card_description', 'From Gandahara in the Kushan period, the Sikri Stupa tells of the life of Buddha in 13 narrative panels. Three photos taken around 1890 show their order in the earliest restoration.'), ('348770cd-a3a2-4b6e-83f7-bd5f5d699022'::uuid, 'card_description', 'On a Breton peninsula rises Barnenez, a Neolithic cairn 72 m long built of 13,000 to 14,000 tons of stone. Separate passages lead to its 11 chambers, some engraved with symbols.'), ('34bbe345-3a0c-4b09-a81b-23ada293da19'::uuid, 'card_description', 'At the Anta da Estria, a megalithic dolmen believed to date to 4000-2500 BC, Carlos Ribeiro identified nine raised slabs but no stones that could have formed a roof.'), ('34c9266e-b55c-4f29-9e6e-eeb547ecfd50'::uuid, 'card_description', 'On a steep rocky plateau of Skye above a fertile valley and the sea, the Iron Age broch of Dun Hallin still stands up to 3.8 metres, oval guard cells flanking its entrance passage.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s002-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
